    # Separator lines mark repeated tile boundaries; their first index sets the tile period.
    py = row_lines[0] + 1 if row_lines else h
    px = col_lines[0] + 1 if col_lines else w
    out = [[bg for _ in range(w)] for _ in range(h)]
    # Preserve separator lines and replicate all non-background pattern cells by their tile phase.
